1	"use server";
2	/**
3	 * Invoice admin server actions (Phase 3).
4	 *
5	 * Both `createInvoice` and `markInvoicePaidManually` are admin-gated. The
6	 * actual Stripe-touching code lives in `@/lib/invoice-creation` so that
7	 * `acceptWorkOrderQuote` (a client-initiated action) can reuse the same
8	 * core path without dragging the admin guard along.
9	 */
10	import { revalidatePath } from "next/cache";
11	import { z } from "zod";
12	import { requireAdmin, AuthError } from "@/lib/actions/auth";
13	import {
14	  createInvoiceForUser,
15	  type InvoiceCreationResult
16	} from "@/lib/invoice-creation";
17	
18	const uuid = z.string().uuid("invalid id");
19	const positiveInt = z
20	  .number()
21	  .int("must be an integer")
22	  .positive("must be > 0")
23	  .max(1_000_000_000, "absurdly large");
24	
25	const createInput = z.object({
26	  user_id: uuid,
27	  // Optional: work-order invoices may have no project yet. Ownership for those
28	  // rows is carried by `user_id` (see lib/invoice-creation.ts + RLS).
29	  project_id: uuid.optional().nullable(),
30	  amount_cents: positiveInt,
31	  currency: z.string().min(3).max(3).optional().default("USD"),
32	  description: z.string().trim().max(2000).optional().nullable(),
33	  work_order_id: uuid.optional()
34	});
35	
36	const createForWorkOrderInput = z.object({ work_order_id: uuid });
37	
38	const markPaidInput = z.object({ id: uuid });
39	
