1	/**
2	 * Shared lead-capture fan-out. Any entry point that produces a lead (the public
3	 * /api/lead form POST, the Calendly webhook, future imports) calls processLead()
4	 * so the Supabase + Apollo + Customer.io + Resend side effects stay in one place.
5	 *
6	 * Every step is best-effort: a failure in one provider never throws out of
7	 * processLead, so one integration being down can't drop the lead on the floor.
8	 */
9	import { createAdminClient } from "@/lib/supabase/server";
10	import { upsertApolloContact } from "@/lib/apollo";
11	import { cioIdentify, cioTrack, isCustomerIoConfigured } from "@/lib/customerio";
12	import { sendEmail } from "@/lib/resend";
13	import {
14	  leadConfirmationToClient,
15	  leadAdminNotification
16	} from "@/lib/resend-templates";
17	
18	export type LeadSource = "book" | "form" | "email" | "typeform" | "other";
19	
20	export interface ProcessLeadInput {
21	  email: string;
22	  name?: string | null;
23	  company?: string | null;
24	  message?: string | null;
25	  source: LeadSource;
26	  utm?: Record<string, string>;
27	  referrer?: string | null;
28	  /** Pre-hashed IP for the audit payload (raw IP never stored). Optional. */
29	  ipHash?: string | null;
30	}
31	
32	export interface ProcessLeadResult {
33	  leadId: string | null;
34	  apolloContactId?: string;
35	}
36	
37	export async function processLead(input: ProcessLeadInput): Promise<ProcessLeadResult> {
38	  const { email, source } = input;
39	  const name = input.name ?? null;
40	  const company = input.company ?? null;
41	  const message = input.message ?? null;
42	  const utm = input.utm ?? {};
43	  const referrer = input.referrer ?? null;
44	
45	  // 1. Write to Supabase leads table (admin client bypasses RLS).
46	  // Schema is now unified — write directly to `leads` and surface real errors
47	  // instead of probing legacy candidate names. If the insert fails, the lead
48	  // still flows through Apollo / Customer.io / Resend below.
49	  let leadId: string | null = null;
50	  try {
51	    const supa = createAdminClient();
52	    const { data, error } = await supa
53	      .from("leads")
54	      .insert({
55	        email,
56	        name,
57	        company,
58	        source,
59	        utm_source: utm.utm_source ?? null,
60	        utm_medium: utm.utm_medium ?? null,
61	        utm_campaign: utm.utm_campaign ?? null,
62	        utm_term: utm.utm_term ?? null,
63	        utm_content: utm.utm_content ?? null,
64	        referrer,
65	        raw_payload: { message, ip_hash: input.ipHash ?? null, ...utm }
66	      })
67	      .select("id")
68	      .single();
69	    if (error) {
70	      console.error("[processLead] leads insert failed:", error.message ?? error);
71	    } else {
72	      leadId = data?.id ?? null;
73	    }
74	  } catch (e) {
75	    console.error("[processLead] Supabase insert threw", e);
76	    // Don't fail the flow if Supabase is down — Apollo + email still try.
