14	/**
15	 * Calendly webhook receiver. Calendly's `invitee.created` payload DOES carry the
16	 * invitee email/name (unlike the client-side embed event), so this is where the
17	 * booking actually becomes a lead in Supabase + Apollo + Customer.io + Resend.
18	 *
19	 * Setup (one-time, outside the app):
20	 *  1. Set CALENDLY_WEBHOOK_SIGNING_KEY (and optionally CALENDLY_API_TOKEN).
21	 *  2. Create a webhook subscription pointing at /api/webhooks/calendly for the
22	 *     `invitee.created` event via Calendly's API.
23	 */
24	export async function POST(request: Request) {
25	  const startedAt = Date.now();
26	  const requestId = request.headers.get("calendly-request-id") ?? crypto.randomUUID();
27	  console.log(
28	    JSON.stringify({
29	      msg: "calendly_webhook_received",
30	      request_id: requestId,
31	      ts: new Date().toISOString()
32	    })
33	  );
34	
35	  if (!isCalendlyWebhookConfigured()) {
36	    console.warn(
37	      JSON.stringify({
38	        msg: "calendly_webhook_not_configured",
39	        request_id: requestId
40	      })
41	    );
42	    return NextResponse.json({ ok: false, error: "not_configured" }, { status: 503 });
43	  }
44	
45	  // Must read the raw body for signature verification (parsing first would break it).
46	  const rawBody = await request.text();
47	  const signingKey = process.env.CALENDLY_WEBHOOK_SIGNING_KEY!;
48	  const valid = verifyCalendlySignature(rawBody, request.headers.get("Calendly-Webhook-Signature"), signingKey);
49	  if (!valid) {
50	    return NextResponse.json({ ok: false, error: "invalid_signature" }, { status: 401 });
51	  }
52	
53	  let evt: CalendlyWebhookEvent;
54	  try {
55	    evt = JSON.parse(rawBody) as CalendlyWebhookEvent;
56	  } catch {
57	    return NextResponse.json({ ok: false, error: "invalid_json" }, { status: 400 });
58	  }
59	
60	  // Only act on new bookings; ack everything else so Calendly stops retrying.
61	  if (evt.event !== "invitee.created") {
62	    return NextResponse.json({ ok: true, ignored: evt.event });
63	  }
64	
