1	/**
2	 * Embedded Claude Agents SDK + Composio Tool Router.
3	 *
4	 * The landing markets "Claude + Composio + MCP integrations" as a core
5	 * Dobeu service — this module makes that real inside the app. It opens a
6	 * per-user Composio tool-router session (Stripe, Vercel, Calendly, Apollo,
7	 * Customer.io, GitHub, and 500+ more) and runs the Agent SDK's `query()`
8	 * against it.
9	 *
10	 * Graceful degradation, matching the rest of the codebase:
11	 *  - If COMPOSIO_API_KEY or ANTHROPIC_API_KEY is unset, runAgent() returns
12	 *    { ok: false, error: "not_configured" } without throwing.
13	 *  - If the SDK packages aren't installed yet, the dynamic imports fail
14	 *    cleanly with { ok: false, error: "sdk_not_installed" } so the rest of
15	 *    the app keeps building.
16	 *
17	 * Security:
18	 *  - Server-only. Never import from a Client Component.
19	 *  - The HTTP surface (app/api/agent/route.ts) is admin-gated via isAdminEmail.
20	 *  - `permissionMode` defaults to "default" (SDK enforces approvals). The
21	 *    `mode` parameter lets trusted, non-interactive callers (cron, batch
22	 *    scripts) opt into "bypassPermissions" — never accept that value
23	 *    from an end-user request body.
24	 *  - Treat all tool output as untrusted external content.
25	 */
26	
27	/**
28	 * Agent permission mode. The safe default is to let the SDK enforce its
29	 * normal approval flow — callers must opt into `bypassPermissions` for
30	 * automation use cases (e.g. cron jobs in scripts/agent.ts) where there is
31	 * no human in the loop. Never accept this value from an end-user request.
32	 */
33	export type AgentPermissionMode = "default" | "acceptEdits" | "plan" | "bypassPermissions";
34	
35	export interface AgentRunInput {
36	  /** A short stable identifier for the calling user — scopes the Composio session. */
37	  userId: string;
38	  /** The natural-language task to run. */
39	  prompt: string;
40	  /** Optional system prompt override. */
41	  systemPrompt?: string;
42	  /**
43	   * Permission mode. Defaults to `"default"` (SDK enforces approvals).
44	   * Pass `"bypassPermissions"` only from trusted, non-interactive contexts.
45	   */
46	  mode?: AgentPermissionMode;
47	}
48	
49	export type AgentRunResult =
50	  | { ok: true; result: string; trace: AgentTraceEntry[] }
51	  | { ok: false; error: AgentError };
52	
53	export type AgentError =
54	  | "not_configured"
55	  | "sdk_not_installed"
56	  | "session_create_failed"
57	  | "query_failed";
58	
59	export interface AgentTraceEntry {
60	  type: string;
61	  subtype?: string;
62	}
63	
64	export function isAgentConfigured(): boolean {
65	  return Boolean(process.env.COMPOSIO_API_KEY && process.env.ANTHROPIC_API_KEY);
66	}
67	
68	export async function runAgent(input: AgentRunInput): Promise<AgentRunResult> {
69	  if (!isAgentConfigured()) return { ok: false, error: "not_configured" };
70	
71	  // Bundler-opaque dynamic import: hides the module specifier from Webpack
72	  // so `next build` doesn't fail with "Module not found" before the SDKs are
73	  // installed. Once `pnpm add @composio/core @anthropic-ai/claude-agent-sdk`
74	  // runs, this resolves at runtime exactly like a normal `import()`.
75	  const dynamicImport = new Function("p", "return import(p)") as <T>(p: string) => Promise<T>;
76	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
77	  let Composio: any;
78	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
79	  let query: any;
80	  try {
81	    ({ Composio } = await dynamicImport<{ Composio: unknown }>("@composio/core"));
82	    ({ query } = await dynamicImport<{ query: unknown }>("@anthropic-ai/claude-agent-sdk"));
83	  } catch (e) {
84	    console.warn("[agent] SDKs not installed:", e instanceof Error ? e.message : e);
85	    return { ok: false, error: "sdk_not_installed" };
86	  }
87	
88	  // Per-user tool-router session. Composio scopes which integrations the
89	  // agent can actually call to those the user has connected.
90	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
91	  let session: any;
92	  try {
93	    const composio = new Composio();
94	    session = await composio.create(input.userId);
95	  } catch (e) {
96	    console.error("[agent] session create failed:", e);
97	    return { ok: false, error: "session_create_failed" };
98	  }
99	
100	  try {
101	    const stream = await query({
102	      prompt: input.prompt,
103	      ...(input.systemPrompt ? { systemPrompt: input.systemPrompt } : {}),
104	      options: {
105	        permissionMode: input.mode ?? "default",
106	        mcpServers: {
107	          composio: session.mcp
108	        }
109	      }
110	    });
111	
112	    let result = "";
113	    const trace: AgentTraceEntry[] = [];
114	    for await (const event of stream) {
115	      trace.push({ type: event.type, subtype: event.subtype });
116	      if (event.type === "result" && event.subtype === "success") {
117	        result += event.result;
118	      }
119	    }
120	    return { ok: true, result, trace };
121	  } catch (e) {
122	    console.error("[agent] query failed:", e);
123	    return { ok: false, error: "query_failed" };
124	  }
125	}
126

